CREATE TABLE IF NOT EXISTS projects (id TEXT PRIMARY KEY, name TEXT NOT NULL, path TEXT NOT NULL, created_at INTEGER NOT NULL, archived_at INTEGER);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES projects(id), harness TEXT NOT NULL, title TEXT NOT NULL, cwd TEXT NOT NULL, worktree_path TEXT, provider_session_id TEXT, kind TEXT NOT NULL CHECK (kind IN ('chat','subagent','epic_worker')), parent_session_id TEXT REFERENCES sessions(id), forked_at_seq INTEGER, spawned_by_seq INTEGER, epic_run_id TEXT, status TEXT NOT NULL CHECK (status IN ('idle','running','errored','archived')), auto_resume INTEGER NOT NULL, created_at INTEGER NOT NULL, last_activity_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS messages (seq INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL REFERENCES sessions(id), turn_id TEXT NOT NULL, item_id TEXT NOT NULL, role TEXT NOT NULL, type TEXT NOT NULL, content TEXT NOT NULL CHECK (json_valid(content)), created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS messages_session_seq_idx ON messages(session_id, seq);
CREATE TABLE IF NOT EXISTS attachments (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id), message_seq INTEGER REFERENCES messages(seq), filename TEXT NOT NULL, mime TEXT NOT NULL, size_bytes INTEGER NOT NULL, sha256 TEXT, rel_path TEXT, status TEXT NOT NULL CHECK (status IN ('pending','complete','failed')), created_at INTEGER NOT NULL);
CREATE VIRTUAL TABLE IF NOT EXISTS messages_fts USING fts5(text, item_id UNINDEXED, seq UNINDEXED, content='', contentless_delete=1);
CREATE VIRTUAL TABLE IF NOT EXISTS sessions_fts USING fts5(title, session_id UNINDEXED, content='', contentless_delete=1);
CREATE TRIGGER IF NOT EXISTS sessions_fts_insert AFTER INSERT ON sessions BEGIN INSERT INTO sessions_fts(rowid, title, session_id) VALUES (new.rowid, new.title, new.id); END;
